CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS token_events (id BIGSERIAL PRIMARY KEY, mint TEXT NOT NULL, creator TEXT, received_at TIMESTAMPTZ NOT NULL, raw_json TEXT NOT NULL, latency_ms BIGINT NOT NULL, UNIQUE(mint, received_at));
CREATE TABLE IF NOT EXISTS trades (id TEXT PRIMARY KEY, mint TEXT NOT NULL, side TEXT NOT NULL, quantity TEXT NOT NULL, requested_value_sol DOUBLE PRECISION NOT NULL, executed_value_sol DOUBLE PRECISION, fees_sol DOUBLE PRECISION, slippage_pct DOUBLE PRECISION NOT NULL, signature TEXT, detected_at TIMESTAMPTZ, submitted_at TIMESTAMPTZ, confirmed_at TIMESTAMPTZ, state TEXT NOT NULL, entry_reason TEXT, exit_reason TEXT, realized_pnl_sol DOUBLE PRECISION, reconciliation_needed BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_trades_mint_state ON trades(mint, state);
CREATE TABLE IF NOT EXISTS rpc_health (endpoint TEXT PRIMARY KEY, checked_at TIMESTAMPTZ NOT NULL, latency_ms BIGINT, healthy BOOLEAN NOT NULL, http_status INTEGER, error TEXT, supports_read BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS risk_assessments (id BIGSERIAL PRIMARY KEY, mint TEXT NOT NULL, approved BOOLEAN NOT NULL, reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS positions (mint TEXT PRIMARY KEY, quantity TEXT NOT NULL, cost_sol DOUBLE PRECISION, status TEXT NOT NULL, opened_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS transactions (id TEXT PRIMARY KEY, trade_id TEXT NOT NULL, signature TEXT, state TEXT NOT NULL, raw_hash TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS operational_logs (id BIGSERIAL PRIMARY KEY, level TEXT NOT NULL, event_type TEXT NOT NULL, message TEXT NOT NULL, payload_json TEXT, created_at TIMESTAMPTZ NOT NULL);
